#!/usr/bin/env python3
"""Generator for Unified Malbolge Relational ALU (ALU_REL):
Pure Malbolge Stack Machine with Simultaneous Arithmetic (ADD 0x02, SUB 0x03)
and Relational Equality Comparison (CMP_EQ 0x04) with Chained Evaluation.

Features:
- Pure Malbolge stack machine with dynamic 2-slot LIFO stack tracking (SLOT0_FLAG, SLOT1_FLAG).
- Simultaneous cohabitation of ADD (0x02), SUB (0x03), and CMP_EQ (0x04) in the same binary image.
- 6-Opcode sequential dispatch: HALT (0x00), PUSH_CONST (0x01), ADD (0x02), SUB (0x03), CMP_EQ (0x04), OUT_BYTE (0x10).
- Cross-arithmetic and relational chained evaluation: (1 + 1) == 2 -> 1, (4 - 2) == 2 -> 1, (4 - 2) == 1 -> 0, etc.
- 100% bit-exact step parity between Classic native C runner and Python reference oracle.
- Binary size strictly under the 59,049 limit: 57,511 bytes (1,538 bytes headroom).
"""
from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path

