def build(hell_path: Path = DEFAULT_OUT, mb_path: Path = DEFAULT_MB, dbg_path: Path = DEFAULT_DBG) -> None:
    hell_path.parent.mkdir(parents=True, exist_ok=True)
    hell_path.write_text(generate(), encoding="utf-8")
    lmao_bin = ROOT / "third_party/lmao/lmao"
    if not lmao_bin.exists():
        lmao_bin = Path("/tmp/lmao_diag")
    cmd = [str(lmao_bin), "-d", "-o", str(mb_path), str(hell_path)]
    res = subprocess.run(cmd, capture_output=True, text=True)
    if res.returncode != 0:
        print("LMAO build failed:", res.stderr)
        sys.exit(1)
    print(f"Built {mb_path} ({len(mb_path.read_bytes())} bytes)")

def main() -> None:
    parser = argparse.ArgumentParser(description="Generate Unified Malbolge Relational ALU mbir_alu_rel.hell")
    parser.add_argument("-o", "--output", type=Path, default=DEFAULT_OUT)
    parser.add_argument("--build", action="store_true", help="Assemble with LMAO into .mb")
    args = parser.parse_args()

    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(generate(), encoding="utf-8")
    print(f"Generated {args.output} ({len(generate())} bytes)")
    if args.build:
        build(args.output)

if __name__ == "__main__":
    main()
